import React, { useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './CoachSignUpForm.css'; // Import the CSS file

const CoachSignUpForm = (props) => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
  });

  const [errors, setErrors] = useState({
    name: '',
    email: '',
    password: '',
  });

  const [error, setError] = useState('');
  const navigate = useNavigate();

  const { name, email, password } = formData;

  // Handles input changes
  const handleChange = (e) => {
    const { name, value } = e.target;

    // Prevent numbers and special characters in the name field
    if (name === 'name' && !/^[A-Za-z\s]*$/.test(value)) {
      return;
    }

    setFormData({ ...formData, [name]: value });
    validateField(name, value);
  };

  // Validate input fields
  const validateField = (fieldName, value) => {
    let errorMsg = '';

    if (fieldName === 'name') {
      errorMsg = value.length < 3 ? 'Name must be at least 3 letters' : '';
    } else if (fieldName === 'email') {
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      errorMsg = !emailPattern.test(value) ? 'Enter a valid email address' : '';
    } else if (fieldName === 'password') {
      errorMsg = value.length < 6 ? 'Password must be at least 6 characters' : '';
    }

    setErrors((prevErrors) => ({ ...prevErrors, [fieldName]: errorMsg }));
  };

  // Function to check if the form is valid
  const isFormValid = () => {
    return !errors.name && !errors.email && !errors.password && name && email && password;
  };

  // Function to register coach
  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!isFormValid()) {
      setError('Please fix validation errors before submitting');
      return;
    }

    try {
      const response = await axios.post('http://localhost:5000/api/coach/signup', {
        name,
        email,
        password,
      });

      const { token, coach } = response.data;

      if (token) {
        localStorage.setItem('coachToken', token);
        localStorage.setItem('coachName', coach.name);
        if (props.onSignup) props.onSignup();
        navigate('/coach/dashboard');
      } else {
        setError('Registration failed. Please try again.');
      }
    } catch (err) {
      console.error('Coach sign up error:', err);
      setError(err.response?.data?.message || 'Registration failed. Please try again.');
    }
  };

  return (
    <div className="signup-form">
      <h2>Coach Sign Up</h2>
      {error && <p className="error">{error}</p>}
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="name"
          placeholder="Name"
          value={name}
          onChange={handleChange}
          required
        />
        {errors.name && <span className="error">{errors.name}</span>}

        <input
          type="email"
          name="email"
          placeholder="Email"
          value={email}
          onChange={handleChange}
          required
        />
        {errors.email && <span className="error">{errors.email}</span>}

        <input
          type="password"
          name="password"
          placeholder="Password"
          value={password}
          onChange={handleChange}
          required
        />
        {errors.password && <span className="error">{errors.password}</span>}

        <button type="submit" disabled={!isFormValid()}>
          Sign Up
        </button>
      </form>
    </div>
  );
};

export default CoachSignUpForm;
